<script setup lang="ts">import {ref} from 'vue';import {salesReceiptsApi} from '@/api/salesReceipts';import {useApiError} from '@/composables/useApiError';const props=defineProps<{receiptId:number}>();const treasuryAccountId=ref<number>();const busy=ref(false);const result=ref<any>();const error=useApiError({scope:'sales'});async function confirm(){if(!treasuryAccountId.value||busy.value)return;busy.value=true;error.clear();try{result.value=await salesReceiptsApi.confirm(props.receiptId,treasuryAccountId.value)}catch(e){error.set(e)}finally{busy.value=false}}</script>
<template><v-card><v-card-title>Receipt confirmation</v-card-title><v-card-text><v-text-field v-model.number="treasuryAccountId" type="number" label="Treasury account"/><v-alert v-if="error.message.value" type="error">{{error.message.value}}</v-alert><v-alert v-if="result" type="success">{{result.status}} · Treasury: {{result.treasuryTransactionId}} · Accounting: {{result.accountingPostingReference}}</v-alert></v-card-text><v-card-actions><v-btn color="primary" :loading="busy" :disabled="!treasuryAccountId" @click="confirm">Confirm receipt</v-btn></v-card-actions></v-card></template>
